CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY,name text NOT NULL,price integer NOT NULL CHECK(price>0),icon text NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY,idempotency_key uuid UNIQUE NOT NULL,cart_id uuid NOT NULL,amount integer NOT NULL,status text NOT NULL CHECK(status IN ('processing','queued','confirmed','failed')),attempts integer NOT NULL DEFAULT 0,trace_context jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_pending ON orders(updated_at) WHERE status IN ('queued','processing');
CREATE TABLE IF NOT EXISTS payments(idempotency_key uuid PRIMARY KEY,order_id uuid NOT NULL,amount integer NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recoveries(id bigserial PRIMARY KEY,fault_id uuid UNIQUE NOT NULL,fault_type text NOT NULL,duration double precision NOT NULL,peak_p95 double precision NOT NULL,peak_error_rate double precision NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
